// Documentation: https://arcg.is/08aL890


// Documentation: https://arcg.is/08aL890


var bgColor = "";
var wait_time = $feature.wait_time;
//var wait_time_low = $feature.wait_time == 300;
//var wait_time_med = $feature.wait_time == 600;
//var wait_time_high = $feature.wait_time == 900;

//var data = $dataSources.dataSource_7-1a024c53367-layer-2.layer;

if (wait_time == 0) {
    bgColor = "#bbd8f1";
    //bgColor = "#FFD2D2"
} else if (wait_time == 300) {
    bgColor = "#e5ece2";
} else if (wait_time == 600) {
    bgColor = "#feedd0";
} else {
    bgColor = "#f0c7d6";
}


return {
    // This controls the background color of the list row item
    // backgroundColor: bgColor 
      background: {
    color: bgColor
  }
};

var bgColor = "";

var data = $dataSources.dataSource_8.layer;
var specificFeature = First(data);

// Grab dates from Econtrol
var CurrentDate = specificFeature.CurrentDate;
var ElectionDateBegin = specificFeature.ElectionDateBegin;
var ElectionDateEnd = specificFeature.ElectionDateEnd;
var EarlyVoteBegin = specificFeature.EarlyVoteBegin;
var EarlyVoteEnd = specificFeature.EarlyVoteEnd;


if (CurrentDate >= ElectionDateBegin && CurrentDate <= ElectionDateEnd) {
    bgColor = "rgba(211, 238, 211, 1)";
} else if (CurrentDate >= EarlyVoteBegin && CurrentDate <= EarlyVoteEnd) {
    bgColor = "rgba(223, 236, 240, 1)";
} else {
    bgColor = "rgba(255, 216, 219, 1)";
}


return {
  background: {
    color: bgColor
  }
};

