parts.exp:
var wait_time = $feature["wait_time"];
var transform = When(wait_time == 0, '0-15', wait_time > 0 && wait_time <= 300, '15-45', wait_time > 300 && wait_time <= 600, '45-60', wait_time > 600, "60+", 'n/a');

return transform

// Open the Suggestions tab and select an existing expression from the map.
// Documentation: https://arcg.is/1G9XqD1#ESRI_SECTION3_302F918A49234190A35BA0AFCD552F8B

// 1. Fetch election begin date and establish UTC
var utcDateBegin = ChangeTimeZone($feature.ElectionDateBegin, "UTC");

// 2. Fetch election end date and establish UTC
var utcDateEnd = ChangeTimeZone($feature.ElectionDateEnd, "UTC");

// 3. Format the begin date output text
var beginDateText = Text(utcDateBegin, "MM/DD/YYYY hh:mm A");

// 4. Format the end date time text
var endDateText = Text(utcDateEnd, "hh:mm A");

// 2. Format the begin date output text (e.g., "MM/DD/YYYY hh:mm A")
return beginDateText + ' - ' + endDateText
